124	func preflightParamsFor(t *testing.T, endpoint string, client *http.Client, auth gitproto.AuthMethod, out *bytes.Buffer) Params {
125		t.Helper()
126		ep, err := transport.ParseURL(endpoint)
127		if err != nil {
128			t.Fatalf("parse endpoint: %v", err)
129		}
130		return Params{
131			SourceConn:    gitproto.NewHTTPConnWithClient(ep, "source", auth, client),
132			SourceService: fakeBootstrapSource{},
133			PushLogger:    slog.New(slog.NewJSONHandler(out, nil)),
134		}
135	}
