137	// withVerboseLog wires p.Logger, the -v log, to a buffer it returns.
138	func withVerboseLog(p *Params) *bytes.Buffer {
139		var out bytes.Buffer
140		p.Logger = slog.New(slog.NewJSONHandler(&out, nil))
141		return &out
142	}
