144	func preflightEvent(t *testing.T, out *bytes.Buffer) map[string]any {
145		t.Helper()
146		var event map[string]any
147		if err := json.Unmarshal(out.Bytes(), &event); err != nil {
148			t.Fatalf("expected exactly one preflight log record: %v; output=%s", err, out)
149		}
150		if event["msg"] != githubPreflightMsg {
151			t.Fatalf("msg = %v, want the preflight record; output=%s", event["msg"], out)
152		}
153		if strings.Contains(out.String(), preflightToken) {
154			t.Fatalf("preflight log leaked the token: %s", out)
155		}
156		return event
157	}
