184		if !ok || limit != defaultTargetMaxPackBytes {
185			t.Fatalf("githubBatchLimit = (%d, %v), want (%d, true): a private repo over the threshold must bootstrap batched",
186				limit, ok, int64(defaultTargetMaxPackBytes))
187		}
