25	
26	// githubBatchLimit asks GitHub how large the source repository is and returns
27	// the batch limit to bootstrap with when it is at or over
28	// githubLargeRepoThresholdKB. It reports false, keeping the one-shot path,
29	// whenever the size is unknown.
30	//
31	// Every lookup it makes is logged through PushLogger, which callers wire
32	// independently of verbose mode, and a failed one is also surfaced as a notice:
33	// it sends a repository of any size as one pack, which an operator has to be
34	// able to see without a code read.
35	func githubBatchLimit(ctx context.Context, p Params) (int64, bool) {
36		if p.TargetMaxPack > 0 || p.SourceConn == nil || p.SourceConn.Endpoint() == nil {
37			return 0, false
38		}
39		if p.SourceService == nil || !p.SourceService.SupportsBootstrapBatch() {
40			return 0, false
41		}
42		lookup, ok := lookupGitHubRepoSize(ctx, p.SourceConn)
43		if !ok || ctx.Err() != nil {
44			// A cancelled run is not a failed lookup, and the bootstrap it would
45			// report on is not going to start.
46			return 0, false
47		}
48		var limit int64
49		if lookup.err == nil && lookup.sizeKB >= githubLargeRepoThresholdKB {
50			limit = defaultTargetMaxPackBytes
51			if p.MaxPackBytes > 0 && p.MaxPackBytes < limit {
52				limit = p.MaxPackBytes
53			}
54		}
55		p.logGitHubPreflight(ctx, lookup, limit)
56		return limit, limit > 0
57	}
58	
59	// githubPreflightTimeout bounds each size-lookup request. The lookup only
60	// chooses between two working strategies, so a stalled API must not hold the
61	// bootstrap. Each attempt gets its own, so a slow refusal does not starve the
62	// anonymous retry. A variable so tests can shorten it.
63	var githubPreflightTimeout = 30 * time.Second
64	
65	// maxGitHubRepoResponseBytes bounds how much of a repository metadata response
66	// is read. The real document is a few KiB.
67	const maxGitHubRepoResponseBytes = 1 << 20
68	
69	// maxGitHubErrorMessageBytes bounds the server-authored message carried into
70	// logs and notices.
71	const maxGitHubErrorMessageBytes = 200
72	
73	// githubPreflightMsg names the size-lookup record in both the verbose log and
74	// PushLogger, so one query finds either.
75	const githubPreflightMsg = "Bootstrap GitHub size preflight"
76	
77	// githubAPIAnswer is the outcome of one request for the repository metadata.
78	type githubAPIAnswer struct {
79		// authenticated reports whether the request that produced the answer
80		// carried credentials; a redirect that stripped them makes it false.
81		authenticated bool
82		status        int   // HTTP status; 0 when no response arrived
83		sizeKB        int64 // valid only when err is nil
84		err           error
85	}
86	
87	// githubSizeLookup is the outcome of one GitHub repository-size lookup.
88	type githubSizeLookup struct {
89		// githubAPIAnswer is the answer the batching decision rests on.
90		githubAPIAnswer
91	
92		owner, repo string
93		// refused is the authenticated attempt the API refused (401/403) before
94		// the anonymous retry; nil when there was none. Its err, always set,
95		// names the real cause (SSO enforcement, an exhausted rate limit) that
96		// the retry's own answer, a 404 for a private repository, would hide.
97		refused *githubAPIAnswer
98	}
99	
100	// lookupGitHubRepoSize asks the GitHub REST API for the size of the source
101	// repository. It reports false when the source is not a GitHub repository
102	// reached over HTTP, in which case no request was made.
103	//
104	// The source connection's credentials go along when it has them for the API
105	// host (see HTTPConn.CredentialsFor): GitHub answers 404 to an anonymous
106	// caller for a private repository, and the anonymous rate limit (60 requests
107	// an hour, shared by everything behind the same egress IP) fails public
108	// lookups too. Credentials from the git credential helper are held only once
109	// the git server asked for them, so a public repository reached through a
110	// helper is still looked up anonymously. A token the API refuses although git
111	// accepted it (one not authorized for an organization's SSO, say) is retried
112	// once anonymously, so a public repository is never worse off than before
113	// credentials were sent.
114	func lookupGitHubRepoSize(ctx context.Context, conn gitproto.Conn) (githubSizeLookup, bool) {
115		httpConn, ok := conn.(*gitproto.HTTPConn)
116		if !ok || httpConn.HTTP == nil {
117			return githubSizeLookup{}, false
118		}
119		owner, repo, ok := GitHubOwnerRepo(conn)
120		if !ok {
121			return githubSizeLookup{}, false
122		}
123		lookup := githubSizeLookup{owner: owner, repo: repo}
124		base, err := url.Parse(GitHubRepoAPIBaseURL)
125		if err != nil {
126			lookup.err = fmt.Errorf("parse github api base url: %w", err)
127			return lookup, true
128		}
129		apiURL := base.JoinPath("repos", owner, repo)
130		if creds := httpConn.CredentialsFor(apiURL); creds != nil {
131			answer := requestGitHubRepoSize(ctx, httpConn.HTTP, apiURL, creds)
132			// Only an answer to a request that still carried the credentials
133			// refuses them; one a redirect stripped them from would get the
134			// same answer again anonymously.
135			refused := answer.status == http.StatusUnauthorized || answer.status == http.StatusForbidden
136			if !refused || !answer.authenticated {
137				lookup.githubAPIAnswer = answer
138				return lookup, true
139			}
140			lookup.refused = &answer
141		}
142		lookup.githubAPIAnswer = requestGitHubRepoSize(ctx, httpConn.HTTP, apiURL, nil)
143		return lookup, true
144	}
145	
146	func requestGitHubRepoSize(ctx context.Context, client *http.Client, apiURL *url.URL, auth gitproto.AuthMethod) githubAPIAnswer {
147		ctx, cancel := context.WithTimeout(ctx, githubPreflightTimeout)
148		defer cancel()
149		var answer githubAPIAnswer
150		req, err := http.NewRequestWithContext(ctx, http.MethodGet, apiURL.String(), nil)
151		if err != nil {
152			answer.err = fmt.Errorf("build request: %w", err)
153			return answer
154		}
155		req.Header.Set("Accept", "application/vnd.github+json")
156		req.Header.Set("X-Github-Api-Version", "2022-11-28")
157		req.Header.Set("User-Agent", useragent.Plain())
158		req.Header.Set(gitproto.StatsPhaseHeader, "github repo metadata")
159		gitproto.ApplyAuth(req, auth)
160		answer.authenticated = req.Header.Get("Authorization") != ""
161		resp, err := client.Do(req)
162		if err != nil {
163			answer.err = err
164			return answer
165		}
166		defer resp.Body.Close()
167		// The redirect guard drops Authorization on a hop that leaves the API's
168		// site, so whether the answer was authenticated is read off the request
169		// that produced it, not the one sent.
170		if resp.Request != nil {
171			answer.authenticated = resp.Request.Header.Get("Authorization") != ""
172		}
173		answer.status = resp.StatusCode
174		body := io.LimitReader(resp.Body, maxGitHubRepoResponseBytes)
175		if resp.StatusCode != http.StatusOK {
176			answer.err = githubAPIError(resp.StatusCode, body)
177			return answer
178		}
179		var payload struct {
180			Size *int64 `json:"size"`
181		}
182		if err := json.NewDecoder(body).Decode(&payload); err != nil {
183			answer.err = fmt.Errorf("decode repository metadata: %w", err)
184			return answer
185		}
186		if payload.Size == nil || *payload.Size < 0 {
187			answer.err = errors.New("repository metadata reports no size")
188			return answer
189		}
190		// GitHub reports 0 for an empty repository and for one whose size it has
191		// not computed yet (a fresh push or import). Bootstrap only runs with
192		// source refs, so here it is the latter: a size as unknown as no size.
193		if *payload.Size == 0 {
194			answer.err = errors.New("repository metadata reports size 0; GitHub may not have sized it yet")
195			return answer
196		}
197		answer.sizeKB = *payload.Size
198		return answer
199	}
200	
201	// githubAPIError describes a non-200 answer, carrying GitHub's own message
202	// ("Not Found", "API rate limit exceeded ...") when the body has one, made
203	// safe and bounded before it reaches a log or a terminal.
204	func githubAPIError(status int, body io.Reader) error {
205		var payload struct {
206			Message string `json:"message"`
207		}
208		if err := json.NewDecoder(body).Decode(&payload); err != nil {
209			return fmt.Errorf("github api returned %d", status)
210		}
211		msg := cleanServerMessage(payload.Message)
212		if msg == "" {
213			return fmt.Errorf("github api returned %d", status)
214		}
215		if len(msg) > maxGitHubErrorMessageBytes {
216			msg = strings.ToValidUTF8(msg[:maxGitHubErrorMessageBytes], "") + "..."
217		}
218		return fmt.Errorf("github api returned %d: %s", status, msg)
219	}
220	
221	// cleanServerMessage makes a server-authored message safe for one log line or
